mapper.select:
SELECT h.id, h.game_id as gameId, g.name as gameName, 
       g.thumbnail_url as thumbnailUrl, h.played_at as playedAt, 
       h.duration_seconds as durationSeconds, h.score 
FROM play_history h 
JOIN games g ON h.game_id = g.id 
WHERE h.user_id = #{userId}

    AND h.game_id = #{gameId}

ORDER BY h.played_at DESC 
LIMIT #{offset}, #{limit}
